<?php
declare(strict_types=1);
namespace App\Modules\Tenancy\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
class ApplicationDraftController extends Controller {
 public static function fields(bool $required=false):array {
  $rule=$required?'required':'sometimes';
  return ['officine_name'=>[$rule,'string','max:180','regex:/\S/u'],'phone'=>[$rule,'string','max:40','regex:/^[+0-9 ()-]{6,40}$/'],'city'=>[$rule,'string','max:120','regex:/\S/u'],'address'=>[$rule,'string','max:500','regex:/\S/u'],'applicant_function'=>[$rule,'string','max:120','regex:/\S/u'],'country'=>[$rule,'string','max:80','regex:/\S/u'],'department'=>[$rule,'string','max:120','regex:/\S/u'],'contact_name'=>[$rule,'string','max:150','regex:/\S/u'],'district'=>['nullable','string','max:120'],'neighborhood'=>['nullable','string','max:120'],'latitude'=>['nullable','numeric','between:-90,90'],'longitude'=>['nullable','numeric','between:-180,180']];
 }
 public static function values(array $data):array {$allowed=array_keys(self::fields());$result=array_intersect_key($data,array_flip($allowed));if(isset($result['officine_name'])){$result['name']=$result['officine_name'];unset($result['officine_name']);}return $result;}
 private function owner(Request $r,string $id,bool $lock=false):object {$q=DB::table('officines')->where('id',$id)->where('applicant_user_id',$r->user()->id);if($lock)$q->lockForUpdate();$o=$q->first();abort_unless($o,404);return $o;}
 public function create(Request $r){return DB::transaction(function()use($r){$u=DB::table('users')->where('id',$r->user()->id)->lockForUpdate()->first();$existing=DB::table('officines')->where('applicant_user_id',$u->id)->where('status','draft')->first();if($existing)return response()->json(['id'=>$existing->id],200);$id=DB::table('officines')->insertGetId(['name'=>'Brouillon d’officine','slug'=>'officine-'.Str::uuid(),'applicant_user_id'=>$u->id,'email'=>$u->email,'contact_name'=>$u->name,'country'=>'Bénin','status'=>'draft','created_at'=>now(),'updated_at'=>now()]);DB::table('officine_user')->insert(['officine_id'=>$id,'user_id'=>$u->id,'permissions'=>'[]','created_at'=>now(),'updated_at'=>now()]);return response()->json(['id'=>$id],201);});}
 public function save(Request $r,string $id){$d=$r->validate(self::fields()+['version'=>['required','integer','min:1']]);DB::transaction(function()use($r,$id,$d){$o=$this->owner($r,$id,true);abort_unless(in_array($o->status,['draft','corrections_requested'],true),409,'Dossier non modifiable.');abort_unless($o->application_version===(int)$d['version'],409,'Version périmée.');DB::table('officines')->where('id',$id)->update(self::values($d)+['application_version'=>$o->application_version+1,'updated_at'=>now()]);});return response()->json(['message'=>'Brouillon enregistré, non soumis.']);}
 public function submit(Request $r,string $id){$d=$r->validate(['version'=>['required','integer','min:1'],'consent'=>['accepted']]);DB::transaction(function()use($r,$id,$d){$o=$this->owner($r,$id,true);abort_unless($r->user()->email_verified_at,403,'Vérifiez votre email avant de soumettre.');abort_unless(in_array($o->status,['draft','corrections_requested'],true),409,'Dossier déjà soumis ou non modifiable.');abort_unless($o->application_version===(int)$d['version'],409,'Version périmée.');$input=(array)$o;$input['officine_name']=$o->name;validator($input,self::fields(true))->validate();DB::table('officines')->where('id',$id)->update(['status'=>'pending','application_version'=>$o->application_version+1,'submitted_at'=>now(),'updated_at'=>now()]);DB::table('tenant_audit_logs')->insert(['officine_id'=>$id,'user_id'=>$r->user()->id,'action'=>'application.submitted','payload'=>json_encode(['attestation_version'=>'2026-11-10','attestation_accepted'=>true,'version'=>$o->application_version+1]),'created_at'=>now(),'updated_at'=>now()]);Outbox::push($r->user()->id,'application:'.$id.':'.($o->application_version+1),'Dossier soumis','Votre demande a été soumise à l’instruction administrative SaaS.',(int)$id);foreach(DB::table('users')->where('is_platform_admin',true)->where('is_active',true)->pluck('id') as $reviewer)Outbox::push($reviewer,'application-review:'.$id.':'.($o->application_version+1).':'.$reviewer,'Nouvelle demande à instruire','Un dossier est disponible dans l’espace d’instruction.',(int)$id);});return response()->json(['message'=>'Dossier soumis.']);}
 private function authorized(Request $r,string $id):object {$o=DB::table('officines')->where('id',$id)->first();abort_unless($o&&($o->applicant_user_id===$r->user()->id||($r->user()->is_platform_admin&&$o->status!=='draft')),404);return $o;}
 public function comments(Request $r,string $id){$this->authorized($r,$id);return response()->json(['data'=>DB::table('application_comments')->where('officine_id',$id)->when(!$r->user()->is_platform_admin,fn($q)=>$q->where('is_internal',false))->orderBy('id')->get(['id','message','is_internal','created_at'])]);}
 public function comment(Request $r,string $id){$this->authorized($r,$id);$d=$r->validate(['message'=>['required','string','max:3000','regex:/\S/u'],'is_internal'=>['required','boolean']]);abort_if($d['is_internal']&&!$r->user()->is_platform_admin,403);DB::transaction(function()use($r,$id,$d){$o=$this->authorized($r,$id);$comment=DB::table('application_comments')->insertGetId($d+['officine_id'=>$id,'user_id'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);DB::table('tenant_audit_logs')->insert(['officine_id'=>$id,'user_id'=>$r->user()->id,'action'=>$d['is_internal']?'application.internal_comment':'application.comment','payload'=>json_encode(['comment_id'=>$comment]),'created_at'=>now(),'updated_at'=>now()]);if($o->status!=='draft'){$recipients=DB::table('users')->where('is_platform_admin',true)->where('is_active',true)->pluck('id');if(!$d['is_internal'])$recipients->push($o->applicant_user_id);foreach($recipients->unique() as $recipient){if($recipient&&$recipient!==$r->user()->id)Outbox::push($recipient,'application-comment:'.$comment.':'.$recipient,'Nouveau message sur un dossier','Un message est disponible dans votre espace autorisé.',(int)$id);}}});return response()->json(['message'=>'Commentaire enregistré.'],201);}
 public function documents(Request $r,string $id){$this->authorized($r,$id);return response()->json(['data'=>DB::table('application_documents')->where('officine_id',$id)->get(['id','name','type','mime','size','sha256','created_at'])]);}
 public function upload(Request $r,string $id){$d=$r->validate(['file'=>['required','file','mimes:pdf,jpg,jpeg,png','max:5120'],'type'=>['required','string','max:120']]);$o=$this->owner($r,$id);abort_unless(in_array($o->status,['draft','corrections_requested'],true),409);$file=$r->file('file');$path=$file->store('applications','local');abort_unless($path,503,'Stockage indisponible.');try{DB::transaction(function()use($r,$id,$d,$file,$path){$o=$this->owner($r,$id,true);abort_unless(in_array($o->status,['draft','corrections_requested'],true),409);abort_if(DB::table('application_documents')->where('officine_id',$id)->count()>=20,422,'20 pièces au maximum.');DB::table('application_documents')->insert(['officine_id'=>$id,'user_id'=>$r->user()->id,'name'=>Str::limit(basename($file->getClientOriginalName()),180,''),'type'=>$d['type'],'path'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'sha256'=>hash_file('sha256',$file->getRealPath()),'created_at'=>now(),'updated_at'=>now()]);});}catch(\Throwable $e){Storage::disk('local')->delete($path);throw $e;}return response()->json(['message'=>'Pièce privée enregistrée. Analyse antivirus non disponible.'],201);}
 public function download(Request $r,string $id,string $documentId){$this->authorized($r,$id);$doc=DB::table('application_documents')->where('officine_id',$id)->where('id',$documentId)->first();abort_unless($doc,404);return Storage::disk('local')->download($doc->path,'piece-'.$doc->id.'.'.(['application/pdf'=>'pdf','image/png'=>'png','image/jpeg'=>'jpg'][$doc->mime]??'bin'),['X-Content-Type-Options'=>'nosniff','Cache-Control'=>'no-store']);}
}
